/**
 * P2PMessageInput Component
 *
 * Renders the message input area with markdown toolbar, preview,
 * file attachment button, and type selector.
 */

import React, { forwardRef } from 'react';
import { Textarea } from '@/components/ui/textarea';
import { shouldSendOnKey } from '@/components/chat/should-send-on-key';
import { Button } from '@/components/ui/button';
import { Send, Paperclip } from 'lucide-react';
import { MarkdownToolbar } from './MarkdownToolbar';
import { TypeSelectorBar } from './TypeSelectorBar';
import ReactMarkdown from 'react-markdown';
import type { MessageType } from '@/types/message-protocol';

interface P2PMessageInputProps {
  inputMessage: string;
  messageType: MessageType;
  showMarkdownPreview: boolean;
  canSendMessages: boolean;
  /** A message is between submit and appearing in the transcript. */
  isSending: boolean;
  onInputChange: (value: string) => void;
  onInputFocus: () => void;
  onInputBlur: () => void;
  onSubmit: () => void;
  onFileClick: () => void;
  onFormat: (format: string, prefix: string, suffix: string) => void;
  onTogglePreview: () => void;
  onMessageTypeChange: (type: MessageType) => void;
}

export const P2PMessageInput: React.ForwardRefExoticComponent<P2PMessageInputProps & React.RefAttributes<HTMLTextAreaElement>> = forwardRef<HTMLTextAreaElement, P2PMessageInputProps>(
  function P2PMessageInput(
    {
      inputMessage,
      messageType,
      showMarkdownPreview,
      canSendMessages,
      isSending,
      onInputChange,
      onInputFocus,
      onInputBlur,
      onSubmit,
      onFileClick,
      onFormat,
      onTogglePreview,
      onMessageTypeChange,
    }: P2PMessageInputProps,
    ref: React.ForwardedRef<HTMLTextAreaElement>
  ) {
    const isMarkdownMode: boolean = messageType === 'markdown';
    const isLiveDocMode: boolean = messageType === 'live_document';

    const handleSubmit = (e: React.FormEvent): void => {
      e.preventDefault();
      onSubmit();
    };

    const getPlaceholder: () => "Type markdown message..." | "Document content (optional)..." | "Type a message..." = (): "Type markdown message..." | "Document content (optional)..." | "Type a message..." => {
      if (isMarkdownMode) return 'Type markdown message...';
      if (isLiveDocMode) return 'Document content (optional)...';
      return 'Type a message...';
    };

    return (
      <div className="border-t border-surface/50 bg-background">
        <MarkdownToolbar
          visible={isMarkdownMode}
          onFormat={onFormat}
          showPreview={showMarkdownPreview}
          onTogglePreview={onTogglePreview}
        />

        {isMarkdownMode && showMarkdownPreview && inputMessage.trim() && (
          <div className="p-4 border-b border-surface/50 bg-background">
            <p className="text-xs text-muted-foreground mb-2">Preview:</p>
            <div className="prose prose-sm dark:prose-invert max-w-none bg-surface rounded-lg p-3 max-h-32 overflow-y-auto">
              <ReactMarkdown>{inputMessage}</ReactMarkdown>
            </div>
          </div>
        )}

        <div className="p-4">
          <form onSubmit={handleSubmit} className="flex gap-2">
            <Button
              type="button"
              size="icon"
              variant="ghost"
              onClick={onFileClick}
              disabled={!canSendMessages}
              className="text-muted-foreground hover:text-foreground hover:bg-foreground/10"
              title="Send file"
            >
              <Paperclip className="h-4 w-4" />
            </Button>
            {/* A textarea, matching the group composer.
                This was an <input> inside a form: Enter submitted natively,
                Shift+Enter could do nothing, and pasted newlines collapsed —
                so the first time somebody pasted a log excerpt or wrote two
                paragraphs to a DM, the product flattened it, while the SAME
                product handled it correctly one screen away. */}
            <Textarea
              ref={ref}
              value={inputMessage}
              onChange={(e) => onInputChange(e.target.value)}
              onKeyDown={(e) => {
                if (shouldSendOnKey(e)) {
                  e.preventDefault();
                  handleSubmit(e);
                }
              }}
              onFocus={onInputFocus}
              onBlur={onInputBlur}
              placeholder={getPlaceholder()}
              // Addressed by id. When this became a Textarea -- the right
              // change; an <input> flattened pasted newlines -- every spec
              // still looked for `input[placeholder*="message"]`, which a
              // textarea is not. The warmup messages that every call and
              // reconnection test sends first have been going nowhere since,
              // reported as "not delivered", which reads as a protocol fault.
              data-testid="p2p-message-input"
              disabled={!canSendMessages}
              rows={1}
              className="flex-1 resize-none bg-surface border-surface text-foreground placeholder-gray-400 focus:border-primary"
            />
            <Button
              type="submit"
              size="icon"
              // Icon-only, so it needs a name of its own: axe reports
              // `critical button-name` without it and a screen reader
              // announces nothing at all.
              aria-label="Send message"
              // isSending is the guard against a second Enter during the
              // send window -- peer registration and CheckState can take tens
              // of seconds, and the text is still in the field for all of it.
              disabled={!canSendMessages || isSending || (!inputMessage.trim() && !isLiveDocMode)}
              aria-busy={isSending}
              className="bg-primary text-primary-foreground"
            >
              <Send className="h-4 w-4" aria-hidden="true" />
            </Button>
          </form>
        </div>

        <TypeSelectorBar
          selectedType={messageType}
          onTypeChange={onMessageTypeChange}
          disabled={!canSendMessages}
        />
      </div>
    );
  }
);
